"use server";

import { revalidatePath } from "next/cache";

// Mock database state for demonstration purposes
let isNotificationEnabled = false;

export async function getNotificationPreference() {
  return isNotificationEnabled;
}

export async function toggleNotificationPreference() {
  // Toggle the preference
  isNotificationEnabled = !isNotificationEnabled;

  // Revalidate the current page path ("/") to reflect the updated data.
  // This causes Next.js to refresh the UI with the new server state WITHOUT redirecting.
  revalidatePath("/");
}

