args.content:
import { getNotificationPreference, toggleNotificationPreference } from "./actions";

export default async function Home() {
  // Fetch the latest state (this runs on the server)
  const isNotificationEnabled = await getNotificationPreference();

  return (
    <main style={{ padding: "2rem", fontFamily: "sans-serif" }}>
      <h1>Settings</h1>

      <p>
        Notifications are currently:{" "}
        <strong>{isNotificationEnabled ? "ON" : "OFF"}</strong>
      </p>

      {/* 
        A Server Action is easily called using the 'action' attribute on a form.
        When submitted, it executes the action and automatically merges the new 
        server state via the revalidatePath function we defined.
      */}
      <form action={toggleNotificationPreference}>
        <button 
          type="submit" 
          style={{ padding: "0.5rem 1rem", cursor: "pointer", marginTop: "1rem" }}
        >
          Toggle Notifications
        </button>
      </form>
    </main>
  );
}

